import { describe, it, expect } from "vitest";

// Simulates a minimal package.json dependencies object as it might appear in a real project.
// The foot-gun: no APM or error-tracking libraries present.
// The fix: at least one recognised observability dependency is present.

const APM_PACKAGES = [
  "@opentelemetry/api",
  "@opentelemetry/sdk-node",
  "dd-trace",
  "newrelic",
  "@honeycombio/opentelemetry-node",
];

const ERROR_TRACKING_PACKAGES = [
  "@sentry/node",
  "@sentry/browser",
  "@sentry/nextjs",
  "rollbar",
  "bugsnag",
  "@bugsnag/js",
];

function hasObservability(
  deps: Record<string, string>,
  devDeps: Record<string, string> = {}
): { hasAPM: boolean; hasErrorTracking: boolean } {
  const allDeps = { ...deps, ...devDeps };
  const keys = Object.keys(allDeps);
  const hasAPM = APM_PACKAGES.some((pkg) => keys.includes(pkg));
  const hasErrorTracking = ERROR_TRACKING_PACKAGES.some((pkg) =>
    keys.includes(pkg)
  );
  return { hasAPM, hasErrorTracking };
}

function observabilityReport(
  deps: Record<string, string>,
  devDeps: Record<string, string> = {}
): string[] {
  const { hasAPM, hasErrorTracking } = hasObservability(deps, devDeps);
  const issues: string[] = [];
  if (!hasAPM) {
    issues.push(
      "No APM library detected (OpenTelemetry/Datadog/NewRelic/Honeycomb). Add one for distributed tracing."
    );
  }
  if (!hasErrorTracking) {
    issues.push(
      "No error-tracking library detected (Sentry/Rollbar/Bugsnag). Add @sentry/node for crash visibility."
    );
  }
  return issues;
}

describe("Observability stack detection", () => {
  it("foot-gun: reports missing APM and error tracking when no observability deps are present", () => {
    // A typical bare-bones project with no observability tooling
    const dependencies: Record<string, string> = {
      express: "^4.18.2",
      lodash: "^4.17.21",
      axios: "^1.4.0",
    };
    const devDependencies: Record<string, string> = {
      typescript: "^5.0.0",
      vitest: "^1.0.0",
    };

    const { hasAPM, hasErrorTracking } = hasObservability(
      dependencies,
      devDependencies
    );
    const issues = observabilityReport(dependencies, devDependencies);

    expect(hasAPM).toBe(false);
    expect(hasErrorTracking).toBe(false);
    expect(issues).toHaveLength(2);
    expect(issues[0]).toMatch(/APM/i);
    expect(issues[1]).toMatch(/error.tracking|sentry/i);
  });

  it("safe fix: no issues reported when both Sentry and OpenTelemetry are present", () => {
    const dependencies: Record<string, string> = {
      express: "^4.18.2",
      "@sentry/node": "^7.80.0",
      "@opentelemetry/api": "^1.6.0",
      "@opentelemetry/sdk-node": "^0.45.0",
    };
    const devDependencies: Record<string, string> = {
      typescript: "^5.0.0",
    };

    const { hasAPM, hasErrorTracking } = hasObservability(
      dependencies,
      devDependencies
    );
    const issues = observabilityReport(dependencies, devDependencies);

    expect(hasAPM).toBe(true);
    expect(hasErrorTracking).toBe(true);
    expect(issues).toHaveLength(0);
  });

  it("safe fix: Datadog dd-trace + Rollbar also satisfies both requirements", () => {
    const dependencies: Record<string, string> = {
      "dd-trace": "^4.10.0",
      rollbar: "^2.26.0",
      fastify: "^4.0.0",
    };

    const { hasAPM, hasErrorTracking } = hasObservability(dependencies);
    const issues = observabilityReport(dependencies);

    expect(hasAPM).toBe(true);
    expect(hasErrorTracking).toBe(true);
    expect(issues).toHaveLength(0);
  });

  it("partial foot-gun: only error tracking present still flags missing APM", () => {
    const dependencies: Record<string, string> = {
      "@sentry/nextjs": "^7.80.0",
      next: "^14.0.0",
    };

    const { hasAPM, hasErrorTracking } = hasObservability(dependencies);
    const issues = observabilityReport(dependencies);

    expect(hasAPM).toBe(false);
    expect(hasErrorTracking).toBe(true);
    expect(issues).toHaveLength(1);
    expect(issues[0]).toMatch(/APM/i);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic simulation of a minimal analytics client and event tracking
// to demonstrate the foot-gun (no telemetry) vs the safe fix (instrumented events).

type AnalyticsEvent = {
  event: string;
  properties?: Record<string, unknown>;
};

class NoOpAnalytics {
  private events: AnalyticsEvent[] = [];

  capture(_event: string, _properties?: Record<string, unknown>): void {
    // foot-gun: silently does nothing — no telemetry recorded
  }

  getCapturedEvents(): AnalyticsEvent[] {
    return this.events;
  }
}

class PostHogLikeAnalytics {
  private events: AnalyticsEvent[] = [];
  private initialized = false;

  init(apiKey: string): void {
    if (!apiKey || apiKey.trim() === "") {
      throw new Error("Analytics init requires a valid API key");
    }
    this.initialized = true;
  }

  capture(event: string, properties?: Record<string, unknown>): void {
    if (!this.initialized) {
      throw new Error("Analytics not initialized. Call init() first.");
    }
    if (!event || event.trim() === "") {
      throw new Error("Event name must not be empty");
    }
    this.events.push({ event, properties });
  }

  getCapturedEvents(): AnalyticsEvent[] {
    return [...this.events];
  }

  isInitialized(): boolean {
    return this.initialized;
  }
}

// Simulates a user journey through key product moments
function simulateUserJourney(analytics: PostHogLikeAnalytics): void {
  analytics.capture("signup", { method: "email" });
  analytics.capture("activation", { feature: "dashboard" });
  analytics.capture("first_value_moment", { action: "created_first_report" });
  analytics.capture("retention", { day: 7 });
  analytics.capture("churn_signal", { reason: "no_activity_14d" });
}

describe("Product Analytics Telemetry", () => {
  it("demonstrates the foot-gun: NoOpAnalytics silently swallows all events, leaving zero visibility into user journeys", () => {
    const analytics = new NoOpAnalytics();

    // These calls succeed without error but record nothing
    analytics.capture("signup", { method: "email" });
    analytics.capture("activation", { feature: "dashboard" });
    analytics.capture("first_value_moment", { action: "created_first_report" });
    analytics.capture("retention", { day: 7 });
    analytics.capture("churn_signal", { reason: "no_activity_14d" });

    const recorded = analytics.getCapturedEvents();

    // Foot-gun: zero events were actually recorded — no telemetry, no insight
    expect(recorded).toHaveLength(0);
    // There is no way to know if users signed up, activated, or churned
    expect(recorded.find((e) => e.event === "signup")).toBeUndefined();
    expect(recorded.find((e) => e.event === "churn_signal")).toBeUndefined();
  });

  it("safe fix: PostHogLikeAnalytics properly initializes and captures all key lifecycle events", () => {
    const analytics = new PostHogLikeAnalytics();

    // Safe fix: initialize with a valid API key before capturing
    analytics.init("phc_test_api_key_abc123");
    expect(analytics.isInitialized()).toBe(true);

    simulateUserJourney(analytics);

    const recorded = analytics.getCapturedEvents();

    // All 5 key events are captured
    expect(recorded).toHaveLength(5);

    const eventNames = recorded.map((e) => e.event);
    expect(eventNames).toContain("signup");
    expect(eventNames).toContain("activation");
    expect(eventNames).toContain("first_value_moment");
    expect(eventNames).toContain("retention");
    expect(eventNames).toContain("churn_signal");

    // Properties are preserved for downstream analysis
    const signupEvent = recorded.find((e) => e.event === "signup");
    expect(signupEvent?.properties).toEqual({ method: "email" });

    const churnEvent = recorded.find((e) => e.event === "churn_signal");
    expect(churnEvent?.properties).toEqual({ reason: "no_activity_14d" });
  });

  it("safe fix: analytics client throws on missing init, preventing silent misconfiguration", () => {
    const analytics = new PostHogLikeAnalytics();

    // Attempting to capture without init should throw — fail loudly, not silently
    expect(() => analytics.capture("signup")).toThrowError(
      "Analytics not initialized. Call init() first."
    );
  });

  it("safe fix: analytics client throws on empty API key, preventing misconfigured deployments", () => {
    const analytics = new PostHogLikeAnalytics();

    expect(() => analytics.init("")).toThrowError(
      "Analytics init requires a valid API key"
    );
    expect(analytics.isInitialized()).toBe(false);
  });

  it("safe fix: analytics client throws on empty event name, enforcing event naming discipline", () => {
    const analytics = new PostHogLikeAnalytics();
    analytics.init("phc_test_api_key_abc123");

    expect(() => analytics.capture("")).toThrowError(
      "Event name must not be empty"
    );

    // No phantom empty events recorded
    expect(analytics.getCapturedEvents()).toHaveLength(0);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic in-memory rate limiter implementations

// --- Foot-gun: No rate limiting on auth endpoint ---
function createUnprotectedAuthHandler() {
  let attemptLog: { ip: string; timestamp: number }[] = [];

  return function handleAuth(ip: string, password: string): { success: boolean; status: number } {
    // No rate limiting — every request is processed regardless of frequency
    attemptLog.push({ ip, timestamp: Date.now() });
    // Simulate password check (only "correct" is valid)
    if (password === "correct") {
      return { success: true, status: 200 };
    }
    return { success: false, status: 401 };
  };
}

// --- Safe fix: Rate-limited auth handler ---
interface RateLimitStore {
  [ip: string]: { count: number; windowStart: number; locked: boolean; lockCount: number };
}

function createRateLimitedAuthHandler({
  maxAttemptsPerWindow = 5,
  windowMs = 60_000,
  lockThreshold = 10,
}: {
  maxAttemptsPerWindow?: number;
  windowMs?: number;
  lockThreshold?: number;
} = {}) {
  const store: RateLimitStore = {};

  return function handleAuth(
    ip: string,
    password: string,
    now: number = Date.now()
  ): { success: boolean; status: number; reason?: string } {
    if (!store[ip]) {
      store[ip] = { count: 0, windowStart: now, locked: false, lockCount: 0 };
    }

    const entry = store[ip];

    // Check account lock
    if (entry.locked) {
      return { success: false, status: 423, reason: "account_locked" };
    }

    // Reset window if expired
    if (now - entry.windowStart > windowMs) {
      entry.count = 0;
      entry.windowStart = now;
    }

    // Enforce per-window rate limit
    if (entry.count >= maxAttemptsPerWindow) {
      return { success: false, status: 429, reason: "rate_limit_exceeded" };
    }

    entry.count += 1;

    if (password === "correct") {
      return { success: true, status: 200 };
    }

    // Track cumulative failures for account locking
    entry.lockCount += 1;
    if (entry.lockCount >= lockThreshold) {
      entry.locked = true;
    }

    return { success: false, status: 401 };
  };
}

describe("Auth Endpoints Rate Limiting", () => {
  describe("Foot-gun: unprotected auth handler allows unlimited attempts", () => {
    it("should allow an attacker to make unlimited auth attempts without any throttling", () => {
      const handleAuth = createUnprotectedAuthHandler();
      const attackerIp = "192.168.1.100";
      const results: number[] = [];

      // Simulate 50 rapid brute-force attempts
      for (let i = 0; i < 50; i++) {
        const result = handleAuth(attackerIp, `wrong_password_${i}`);
        results.push(result.status);
      }

      // All 50 attempts are processed — no 429 or 423 ever returned
      const rateLimitedCount = results.filter((s) => s === 429 || s === 423).length;
      expect(rateLimitedCount).toBe(0);

      // Every single attempt gets a real 401 response (auth system is fully exposed)
      const processedCount = results.filter((s) => s === 401).length;
      expect(processedCount).toBe(50);
    });

    it("should allow the correct password to succeed even after many failures (no lockout)", () => {
      const handleAuth = createUnprotectedAuthHandler();
      const attackerIp = "10.0.0.1";

      // 100 failed attempts
      for (let i = 0; i < 100; i++) {
        handleAuth(attackerIp, "wrong");
      }

      // Still succeeds — no lockout mechanism
      const result = handleAuth(attackerIp, "correct");
      expect(result.status).toBe(200);
      expect(result.success).toBe(true);
    });
  });

  describe("Safe fix: rate-limited auth handler enforces attempt limits", () => {
    it("should allow up to maxAttemptsPerWindow attempts and then return 429", () => {
      const handleAuth = createRateLimitedAuthHandler({ maxAttemptsPerWindow: 5, windowMs: 60_000 });
      const ip = "192.168.1.200";
      const baseTime = 1_000_000;

      const results: number[] = [];

      // Make 8 attempts within the same window
      for (let i = 0; i < 8; i++) {
        const result = handleAuth(ip, "wrong", baseTime + i * 100); // 100ms apart, same window
        results.push(result.status);
      }

      // First 5 should be 401 (processed but failed)
      expect(results.slice(0, 5).every((s) => s === 401)).toBe(true);

      // Attempts 6-8 should be rate-limited with 429
      expect(results.slice(5).every((s) => s === 429)).toBe(true);
    });

    it("should reset the rate limit counter after the time window expires", () => {
      const handleAuth = createRateLimitedAuthHandler({ maxAttemptsPerWindow: 5, windowMs: 60_000 });
      const ip = "192.168.1.201";
      const baseTime = 2_000_000;

      // Exhaust the window
      for (let i = 0; i < 5; i++) {
        handleAuth(ip, "wrong", baseTime + i * 100);
      }

      // Next attempt in same window is rate-limited
      const blockedResult = handleAuth(ip, "wrong", baseTime + 500);
      expect(blockedResult.status).toBe(429);

      // After window expires (61 seconds later), attempts are allowed again
      const afterWindowResult = handleAuth(ip, "wrong", baseTime + 61_000);
      expect(afterWindowResult.status).toBe(401); // processed, not rate-limited
    });

    it("should lock the account after reaching the lockThreshold cumulative failures", () => {
      const handleAuth = createRateLimitedAuthHandler({
        maxAttemptsPerWindow: 5,
        windowMs: 60_000,
        lockThreshold: 10,
      });
      const ip = "192.168.1.202";
      let baseTime = 3_000_000;

      // Make 10 failed attempts across two windows to trigger lockout
      for (let window = 0; window < 2; window++) {
        for (let i = 0; i < 5; i++) {
          handleAuth(ip, "wrong", baseTime + i * 100);
        }
        baseTime += 61_000; // advance to next window
      }

      // Account should now be locked
      const lockedResult = handleAuth(ip, "correct", baseTime + 100);
      expect(lockedResult.status).toBe(423);
      expect(lockedResult.reason).toBe("account_locked");
      expect(lockedResult.success).toBe(false);
    });

    it("should allow a successful login within the rate limit window", () => {
      const handleAuth = createRateLimitedAuthHandler({ maxAttemptsPerWindow: 5, windowMs: 60_000 });
      const ip = "192.168.1.203";
      const baseTime = 4_000_000;

      // 2 failed attempts then a correct one
      handleAuth(ip, "wrong", baseTime);
      handleAuth(ip, "wrong", baseTime + 100);
      const result = handleAuth(ip, "correct", baseTime + 200);

      expect(result.status).toBe(200);
      expect(result.success).toBe(true);
    });

    it("should isolate rate limits per IP address", () => {
      const handleAuth = createRateLimitedAuthHandler({ maxAttemptsPerWindow: 5, windowMs: 60_000 });
      const attackerIp = "10.0.0.99";
      const legitimateIp = "10.0.0.1";
      const baseTime = 5_000_000;

      // Attacker exhausts their limit
      for (let i = 0; i < 5; i++) {
        handleAuth(attackerIp, "wrong", baseTime + i * 10);
      }
      const attackerBlocked = handleAuth(attackerIp, "wrong", baseTime + 100);
      expect(attackerBlocked.status).toBe(429);

      // Legitimate user from different IP is unaffected
      const legitimateResult = handleAuth(legitimateIp, "correct", baseTime + 100);
      expect(legitimateResult.status).toBe(200);
      expect(legitimateResult.success).toBe(true);
    });
  });
});
